from produire import produire,paras,steps,table
from medicaments_suite import tobramycine
parts=[
('La {blépharite} est une inflammation du bord des paupières. Elle peut toucher la base des cils ou la région des glandes de Meibomius. Les formes antérieure et postérieure peuvent coexister.',paras('La blépharite antérieure intéresse peau, cils et follicules. La forme postérieure est souvent liée au dysfonctionnement des glandes de Meibomius, dont les sécrétions contribuent au film lacrymal.', 'Une blépharoconjonctivite associe inflammation palpébrale et conjonctivale. Un orgelet est un foyer nodulaire douloureux ; un chalazion correspond à une lésion glandulaire localisée, et ne désigne pas toute inflammation du bord libre.')),
('Le {contexte est souvent chronique et récidivant}. Rosacée, dermatite séborrhéique et sécheresse peuvent être associées. Le diagnostic ne nécessite pas de supposer une infection bactérienne dans tous les cas.',paras('Les HUG et le College of Optometrists décrivent une affection fréquente, sans fournir ici de prévalence suisse comparative permettant de classer les dix causes de rougeur. Une rechute n’implique pas nécessairement une résistance antibiotique.', 'La flore cutanée, une inflammation séborrhéique, une dysfonction glandulaire ou des acariens Demodex peuvent intervenir. Les données publiques européennes ne justifient pas une méthode instrumentale ou un antiparasitaire particulier pour tout patient.')),
('Le {mécanisme altère le bord palpébral et le film lacrymal}. Une inflammation des follicules peut produire des croûtes. Une sécrétion glandulaire perturbée favorise l’évaporation des larmes.',paras('Les glandes de Meibomius s’ouvrent près du bord postérieur de la paupière. Leur obstruction ou leur dysfonction peut déstabiliser la couche lipidique du film lacrymal et entretenir irritation et sécheresse.', 'L’inflammation peut s’étendre à la conjonctive ; des infiltrats cornéens peuvent compliquer les formes staphylococciques sévères. Une atteinte de la cornée modifie l’urgence et ne se résume plus à une toilette des paupières.')),
('Le {tri recherche une complication cornéenne ou une autre maladie}. Douleur forte, photophobie ou baisse visuelle imposent une évaluation urgente. Une tuméfaction qui s’étend ne doit pas être traitée comme une simple croûte.',paras('Devant une rougeur douloureuse chez un porteur de lentilles, rechercher une kératite. Douleur aux mouvements, diplopie, protrusion de l’œil ou altération générale font craindre une atteinte orbitaire et justifient une orientation immédiate.', 'Une affection unilatérale persistante, une lésion infiltrée ou une perte focale des cils doit faire rechercher une lésion palpébrale tumorale. Le College signale notamment le carcinome des glandes de Meibomius parmi les situations nécessitant une filière spécialisée.')),
('L’{anamnèse précise le rythme et les traitements essayés}. Demander prurit, brûlure, croûtes matinales et fluctuations visuelles. Rechercher lentilles, cosmétiques, rosacée et récidives.',paras('La gêne est souvent plus marquée le matin ; une sécheresse associée peut toutefois s’aggraver au fil de la journée. Noter douleur profonde, vision réellement diminuée, photophobie, fièvre et caractère unilatéral inhabituel.', 'Relever produits appliqués, allergies, fréquence des soins et qualité de la technique. Avant un antibiotique, identifier la formulation, l’âge, une grossesse ou un allaitement et les autres médicaments ; une pommade cutanée n’est pas automatiquement utilisable dans l’œil.')),
('L’{examen observe cils, bord libre et surface oculaire}. Mesurer la vision et comparer les deux yeux. Chercher croûtes, rougeur, anomalies glandulaires et lésion focale.',paras('Examiner les bords antérieur et postérieur, la fermeture palpébrale et la conjonctive. À la lampe à fente, préciser l’état des orifices glandulaires, du film lacrymal et de la cornée.', 'Une coloration adaptée recherche une atteinte épithéliale si le contexte l’exige. Ne pas conclure à une blépharite simple sur les seules croûtes si la cornée est opaque, douloureuse ou si la vision reste anormale.')),
('L’{approche syndromique distingue les mécanismes dominants}. Une atteinte des cils oriente vers la forme antérieure. Une dysfonction des glandes oriente vers la forme postérieure.',table(['Tableau','Interprétation et décision'],[['Croûtes et inflammation des follicules.','Blépharite antérieure ; discuter composante bactérienne ou séborrhéique.'],['Bord postérieur et glandes anormales, sécheresse.','Dysfonction meibomienne ; soins adaptés et avis spécialisé selon évolution.'],['Prurit avec produits appliqués récemment.','Dermatite de contact possible ; revoir l’exposition.'],['Nodule douloureux localisé.','Orgelet à différencier d’une inflammation diffuse.'],['Lésion persistante unilatérale ou perte focale des cils.','Ne pas multiplier les traitements empiriques ; rechercher une lésion tumorale.'],['Douleur, photophobie ou vision diminuée.','Évaluer la cornée et les causes intraoculaires en urgence.']])) ,
('Le {diagnostic positif est principalement clinique}. Il repose sur une inflammation du bord libre compatible avec l’histoire. L’absence de complication doit être établie avant une prise en charge simple.',paras('La lampe à fente aide à préciser le sous-type et les lésions associées. La présence de bactéries cutanées n’établit pas à elle seule une infection nécessitant un traitement.', 'Une réponse partielle aux soins n’exclut pas une sécheresse associée. Une récidive toujours au même endroit ou une évolution inhabituelle conduit à reconsidérer le diagnostic plutôt qu’à renouveler automatiquement une pommade.')),
('Les {examens complémentaires répondent à une question précise}. Un bilan sanguin ou une culture n’est pas systématique dans une forme typique simple. Une forme atypique ou réfractaire justifie une évaluation ciblée.',paras('L’ophtalmologue choisit les explorations de la surface et des paupières selon les lésions. Une suspicion d’infection cornéenne relève du parcours de kératite, avec prélèvement selon indication et sans retard dangereux de traitement.', 'Une lésion suspecte peut nécessiter une biopsie organisée par le spécialiste. Une recherche de Demodex dépend des signes cliniques et ne justifie pas l’usage domestique de produits concentrés ou irritants près de la cornée.')),
('L’{algorithme commence par la sécurité de l’œil}. Les soins locaux viennent après l’exclusion des alarmes. L’échec entraîne une réévaluation du mécanisme.',steps('Mesurer la vision et rechercher douleur forte, photophobie, atteinte cornéenne et extension de la tuméfaction.', 'Orienter en urgence si alarme ; rechercher une lésion focale suspecte si tableau persistant unilatéral.', 'Identifier forme antérieure, postérieure ou mixte et facteurs associés.', 'Expliquer soins palpébraux et traitement de la sécheresse éventuelle ; réserver l’antibiotique à une indication définie.', 'Contrôler la réponse et la technique ; adresser les formes chroniques, réfractaires ou compliquées.')),
('La {prise en charge suisse repose sur des soins adaptés et une prescription ciblée}. Nettoyer doucement le bord palpébral et traiter les facteurs associés. Un antibiotique ophtalmique se discute lorsqu’une composante bactérienne le justifie.',paras('Les HUG proposent des compresses chaudes quatre fois par jour, l’ablation douce des croûtes et des massages palpébraux verticaux. Utiliser une chaleur confortable, sans brûlure, et éviter le frottement de la cornée ; faire démontrer le geste si nécessaire.', 'Le College décrit l’hygiène régulière comme base du contrôle à long terme. Ces soins ne garantissent pas une guérison définitive ; la nécessité d’un antibiotique dépend de la forme, de la sévérité et de l’examen.', '@@MEDICAMENTS@@', 'Une sécheresse associée peut bénéficier d’un lubrifiant adapté, selon sa notice. Les corticoïdes locaux, traitements systémiques et interventions instrumentales relèvent d’une indication et d’un suivi spécialisés ; ne pas les ajouter à une rougeur indifférenciée.')),
('La {prévention des récidives repose sur une routine tolérable}. Expliquer les soins et vérifier leur réalisation. Adapter lentilles et produits irritants pendant les poussées.',paras('Se laver les mains, utiliser un matériel propre et ne pas partager les produits oculaires. Éviter maquillage ou produit clairement irritant jusqu’à réévaluation ; ne pas arracher brutalement les croûtes.', 'Fixer le suivi selon la gravité et le traitement choisi. L’absence de réponse, les récidives persistantes ou une modification des symptômes imposent un avis ophtalmologique ; douleur importante ou baisse visuelle demandent une réévaluation urgente.')),
('Le {point clé} est de distinguer inflammation chronique et infection à traiter. Le bord palpébral, les glandes et la cornée doivent être évalués ensemble. Les restrictions pédiatriques dépendent de la formulation prescrite.',paras('Hygiène, traitement des facteurs associés et suivi constituent la base. Une dose générale de tobramycine ne dispense pas de lire les précautions spécifiques au collyre contenant du bore.'))]
quiz=[('Les formes antérieure et postérieure peuvent-elles coexister ?','Oui.'),('La forme postérieure implique souvent quelles glandes ?','Les glandes de Meibomius.'),('Toute blépharite impose-t-elle un antibiotique ?','Non, il faut une indication adaptée au mécanisme et à l’examen.'),('Une photophobie importante reste-t-elle compatible avec une simple toilette sans examen ?','Non, rechercher une complication ou une autre affection.'),('Quel examen fonctionnel est essentiel ?','La mesure de la vision.'),('Pourquoi une lésion toujours unilatérale et au même endroit inquiète-t-elle ?','Elle peut correspondre à une lésion focale, notamment tumorale.'),('L’hygiène régulière garantit-elle une guérison définitive ?','Non, elle contribue au contrôle d’une affection souvent chronique.'),('Faut-il arracher les croûtes ?','Non, les retirer doucement après soins adaptés.'),('Une pommade cutanée est-elle interchangeable avec une pommade ophtalmique ?','Non.'),('La phrase posologique dès deux mois autorise-t-elle le collyre Tobrex à cet âge ?','Non, ses précautions liées au bore imposent des restrictions supplémentaires.'),('Quelle durée est fixée par la rubrique posologique AIPS citée pour la blépharite ?','Aucune durée spécifique ; les dix jours proviennent du protocole HUG, pas de cette rubrique AIPS.'),('Peut-on prolonger indéfiniment l’antibiotique en cas de rechute ?','Non, risque de résistance ou de surinfection ; réévaluer.'),('Que faire devant une hypersensibilité à la tobramycine ?','Arrêter et consulter.'),('Que vérifier en cas d’échec des soins ?','Technique, observance, mécanisme, complication et diagnostic concurrent.')]
produire(5,parts,quiz,(1,16,18),tobramycine)
